content.text:
{
  "name": "无人车本地网页控制器",
  "name_en": "Local Web Controller for Robotic Car",
  "manufacturer": "",
  "description": "一种面向小型无人车或智能车实验的浏览器控制与监视终端，用于显示前视摄像头画面、发送转向和油门指令、切换驾驶模式，并支持校准和记录状态查看。",
  "description_en": "A browser-based control and monitoring interface for small robotic or autonomous car experiments. It is used to display the forward camera view, send steering and throttle commands, switch drive modes, and support calibration and recording status display.",
  "tag_hints": [
    "robot car teleoperation",
    "FPV video streaming",
    "steering and throttle control",
    "web-based calibration",
    "drive mode control",
    "browser HMI"
  ],
  "actions": [
    {
      "action_name": "auto-update",
      "description": "启动本地网页控制服务。",
      "description_en": "Start the local web control service."
    },
    {
      "action_name": "auto-update_wsclients",
      "description": "向已连接的网页客户端推送更新数据。",
      "description_en": "Push updated data to connected web clients."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程化循环中更新图像、记录计数和模式状态，并处理网页控制交互。",
      "description_en": "In a threaded loop, update image, record count, and mode status, and handle web control interaction."
    },
    {
      "action_name": "auto-run",
      "description": "运行网页控制循环，更新显示状态并处理控制输入。",
      "description_en": "Run the web control loop, update displayed status, and handle control input."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭本地网页控制服务。",
      "description_en": "Shut down the local web control service."
    }
  ]
}

